				errors.push('密码需要包含至少一个大写字母');
			}
			if (!/[0-9]/.test(trimmedPassword)) {
				errors.push('密码需要包含至少一个数字');
			}
		}

		return {
			isValid: errors.length === 0,
			errors			// 等价于：errors : errors
		};
	}
