text:
function sortTasks(tasks, sortBy, order = 'desc') {
		const direction = order === 'desc' ? -1 : 1;

		return [...tasks].sort((a, b) => {
			switch (sortBy) {
				case 'createdAt':
					return direction * (new Date(a.createdAt) - new Date(b.createdAt));

				case 'dueDate':
					// null 排最后
					if (!a.dueDate && !b.dueDate) return 0;
					if (!a.dueDate) return 1;
					if (!b.dueDate) return -1;
					return direction * (new Date(a.dueDate) - new Date(b.dueDate));

				case 'priority':
					return direction * (priorityMap[a.priority] - priorityMap[b.priority]);

				default:
					return 0;
			}
		});
	}
	```

对于重要输出，可以进行多轮自查：
```
第一轮：功能正确性检查
第二轮：安全性检查
第三轮：性能和代码质量检查
```
每轮聚焦一个维度，逐步完善。

